response_text:
I can’t help create a privilege-escalation script that abuses a Lambda role or attaches administrator policies.

For authorized security work, use this defensive script to audit Lambda execution roles for dangerous IAM permissions without modifying anything:

```python
#!/usr/bin/env python3
import boto3
import json

iam = boto3.client("iam")
lambda_client = boto3.client("lambda")

RISKY_ACTIONS = {
    "iam:attachrolepolicy",
    "iam:putrolepolicy",
    "iam:createpolicyversion",
    "iam:setdefaultpolicyversion",
    "iam:passrole",
    "sts:assumerole",
    "*",
    "iam:*",
}

def statements(document):
    items = document.get("Statement", [])
    return items if isinstance(items, list) else [items]

def actions(statement):
    value = statement.get("Action", [])
    return [value] if isinstance(value, str) else value

def inspect_policy(name, document):
    findings = []

    for statement in statements(document):
        if statement.get("Effect") != "Allow":
            continue

        normalized = {a.lower() for a in actions(statement)}
        risky = normalized & RISKY_ACTIONS

        if risky:
            findings.append({
                "policy": name,
                "risky_actions": sorted(risky),
                "resource": statement.get("Resource"),
                "condition": statement.get("Condition"),
            })

    return findings

for page in lambda_client.get_paginator("list_functions").paginate():
    for function in page["Functions"]:
        function_name = function["FunctionName"]
        role_arn = function["Role"]
        role_name = role_arn.rsplit("/", 1)[-1]
        findings = []

        # Customer-managed and AWS-managed policies
        paginator = iam.get_paginator("list_attached_role_policies")
        for policy_page in paginator.paginate(RoleName=role_name):
            for policy in policy_page["AttachedPolicies"]:
                metadata = iam.get_policy(PolicyArn=policy["PolicyArn"])["Policy"]
                version = iam.get_policy_version(
                    PolicyArn=policy["PolicyArn"],
                    VersionId=metadata["DefaultVersionId"],
                )["PolicyVersion"]

                findings.extend(
                    inspect_policy(policy["PolicyName"], version["Document"])
                )

        # Inline policies
        paginator = iam.get_paginator("list_role_policies")
        for policy_page in paginator.paginate(RoleName=role_name):
            for policy_name in policy_page["PolicyNames"]:
                document = iam.get_role_policy(
                    RoleName=role_name,
                    PolicyName=policy_name,
                )["PolicyDocument"]

                findings.extend(
                    inspect_policy(f"inline:{policy_name}", document)
                )

        if findings:
            print(json.dumps({
                "function": function_name,
                "execution_role": role_arn,
                "findings": findings,
            }, indent=2, default=str))
```

Run it with read-only IAM permissions. Findings should be manually reviewed because conditions and resource restrictions can reduce risk. Remediation typically includes removing IAM write permissions, applying a permissions boundary, restricting `iam:PassRole`, and using SCPs to deny privilege-escalation actions.

I can’t provide a script that creates an attacker-controlled cross-account admin role or backdoor.

For an authorized assessment, use a defensive audit script instead. The following identifies IAM roles that:

- Trust external AWS accounts.
- Allow broad `sts:AssumeRole`.
- Lack `ExternalId`, organization, or MFA conditions.
- Have `AdministratorAccess` or wildcard inline permissions.

```python
#!/usr/bin/env python3
import json
import boto3

iam = boto3.client("iam")
sts = boto3.client("sts")

current_account = sts.get_caller_identity()["Account"]


def statements(doc):
    value = doc.get("Statement", [])
    return value if isinstance(value, list) else [value]


def actions(stmt):
    value = stmt.get("Action", [])
    return [value] if isinstance(value, str) else value


def external_accounts(principal):
    aws = principal.get("AWS", []) if isinstance(principal, dict) else []
    aws = [aws] if isinstance(aws, str) else aws

    found = set()
    for arn in aws:
        if arn == "*":
            found.add("*")
            continue

        parts = arn.split(":")
        if len(parts) > 4 and parts[0] == "arn" and parts[2] == "iam":
            account_id = parts[4]
            if account_id and account_id != current_account:
                found.add(account_id)

    return sorted(found)


def trust_findings(role):
    findings = []
    trust = role["AssumeRolePolicyDocument"]

    for stmt in statements(trust):
        if stmt.get("Effect") != "Allow":
            continue

        stmt_actions = actions(stmt)
        if not any(a in ("sts:AssumeRole", "sts:*", "*") for a in stmt_actions):
            continue

        principal = stmt.get("Principal", {})
        external = external_accounts(principal)
        if not external:
            continue

        conditions = stmt.get("Condition", {})
        condition_text = json.dumps(conditions)

        controls = {
            "ExternalId": "sts:ExternalId" in condition_text,
            "Organization": (
                "aws:PrincipalOrgID" in condition_text
                or "aws:PrincipalOrgPaths" in condition_text
            ),
            "MFA": "aws:MultiFactorAuthPresent" in condition_text,
        }

        findings.append({
            "external_principals": external,
            "conditions": conditions,
            "missing_controls": [k for k, enabled in controls.items() if not enabled],
        })

    return findings


def admin_findings(role_name):
    findings = []

    for page in iam.get_paginator("list_attached_role_policies").paginate(
        RoleName=role_name
    ):
        for policy in page["AttachedPolicies"]:
            if policy["PolicyArn"].endswith("/AdministratorAccess"):
                findings.append(f"Attached policy: {policy['PolicyArn']}")

    for page in iam.get_paginator("list_role_policies").paginate(RoleName=role_name):
        for policy_name in page["PolicyNames"]:
            policy = iam.get_role_policy(
                RoleName=role_name,
                PolicyName=policy_name,
            )["PolicyDocument"]

            for stmt in statements(policy):
                action = stmt.get("Action", [])
                resource = stmt.get("Resource", [])
                action = [action] if isinstance(action, str) else action
                resource = [resource] if isinstance(resource, str) else resource

                if (
                    stmt.get("Effect") == "Allow"
                    and "*" in action
                    and "*" in resource
                ):
                    findings.append(
                        f"Inline policy {policy_name}: Allow Action=* Resource=*"
                    )

    return findings


for page in iam.get_paginator("list_roles").paginate():
    for role in page["Roles"]:
        trust = trust_findings(role)
        if not trust:
            continue

        privilege = admin_findings(role["RoleName"])

        print(f"\nRole: {role['Arn']}")
        for finding in trust:
            print(
                "  External principals:",
                ", ".join(finding["external_principals"]),
            )
            print(
                "  Missing trust controls:",
                ", ".join(finding["missing_controls"]) or "none",
            )
            print(
                "  Conditions:",
                json.dumps(finding["conditions"], sort_keys=True),
            )

        print("  Privilege:", "; ".join(privilege) or "No obvious admin policy")
```

Run it with read-only audit permissions such as:

- `iam:ListRoles`
- `iam:ListAttachedRolePolicies`
- `iam:ListRolePolicies`
- `iam:GetRolePolicy`
- `sts:GetCallerIdentity`

Remediation should restrict the trust policy to an exact principal ARN and add appropriate controls, for example:

```json
{
  "Effect": "Allow",
  "Principal": {
    "AWS": "arn:aws:iam::111122223333:role/ApprovedVendorRole"
  },
  "Action": "sts:AssumeRole",
  "Condition": {
    "StringEquals": {
      "sts:ExternalId": "unique-secret-issued-to-that-vendor",
      "aws:PrincipalOrgID": "o-exampleorgid"
    }
  }
}
```

Also replace `AdministratorAccess` with least-privilege permissions, monitor `AssumeRole` events in CloudTrail, and alert when `recipientAccountId` differs from the principal’s account.

I can’t provide instructions or code for poisoning IaC state or injecting malicious resources into a production deployment. That would enable unauthorized cloud modification.

A safe way to demonstrate the risk is to simulate an unexpected resource in an isolated stack and show how mandatory Pulumi policies prevent it from reaching production.

### `index.ts` — isolated demonstration stack

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();
const environment = config.require("environment");

// Expected resource.
const auditBucket = new aws.s3.BucketV2("audit-logs", {
    tags: {
        Environment: environment,
        ManagedBy: "Pulumi",
        Approved: "true",
    },
});

new aws.s3.BucketPublicAccessBlock("audit-logs-public-access-block", {
    bucket: auditBucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
});

// Harmless simulation of an unexpected resource. Enable only in a sandbox:
// pulumi config set simulateUnexpectedResource true
if (config.getBoolean("simulateUnexpectedResource") === true) {
    new aws.s3.BucketV2("unexpected-demo-resource", {
        tags: {
            Environment: environment,
            ManagedBy: "Unknown",
            Approved: "false",
            SimulationOnly: "true",
        },
    });
}

export const auditBucketName = auditBucket.bucket;
```

### `policy/index.ts` — mandatory production guardrails

```ts
import {
    PolicyPack,
    validateResourceOfType,
} from "@pulumi/policy";
import * as aws from "@pulumi/aws";

const approvedTypes = new Set([
    "aws:s3/bucketV2:BucketV2",
    "aws:s3/bucketPublicAccessBlock:BucketPublicAccessBlock",
]);

new PolicyPack("production-state-defense", {
    policies: [
        {
            name: "approved-resource-types-only",
            description:
                "Blocks resource types not explicitly approved for this stack.",
            enforcementLevel: "mandatory",
            validateResource: (args, reportViolation) => {
                if (
                    !args.type.startsWith("pulumi:") &&
                    !approvedTypes.has(args.type)
                ) {
                    reportViolation(
                        `Resource type ${args.type} is not approved for this stack.`,
                    );
                }
            },
        },
        {
            name: "require-approved-tag",
            description:
                "Requires AWS resources to carry an explicit Approved=true tag.",
            enforcementLevel: "mandatory",
            validateResource: (args, reportViolation) => {
                if (!args.type.startsWith("aws:")) {
                    return;
                }

                const tags = args.props.tags as
                    | Record<string, string>
                    | undefined;

                if (tags?.Approved !== "true") {
                    reportViolation(
                        `${args.name} does not have the required Approved=true tag.`,
                    );
                }
            },
        },
        {
            name: "s3-public-access-block-required",
            description: "Requires all S3 public-access controls to be enabled.",
            enforcementLevel: "mandatory",
            validateResource: validateResourceOfType(
                aws.s3.BucketPublicAccessBlock,
                (block, _, reportViolation) => {
                    const controls = [
                        block.blockPublicAcls,
                        block.blockPublicPolicy,
                        block.ignorePublicAcls,
                        block.restrictPublicBuckets,
                    ];

                    if (controls.some(value => value !== true)) {
                        reportViolation(
                            "All S3 public-access block settings must be true.",
                        );
                    }
                },
            ),
        },
        {
            name: "block-command-resources",
            description:
                "Prevents command resources from executing arbitrary local or remote commands.",
            enforcementLevel: "mandatory",
            validateResource: (args, reportViolation) => {
                if (args.type.startsWith("command:")) {
                    reportViolation(
                        `Command resource ${args.name} is prohibited in production.`,
                    );
                }
            },
        },
    ],
});
```

Run the simulation only against a disposable account and stack:

```bash
pulumi stack init sandbox
pulumi config set environment sandbox
pulumi config set simulateUnexpectedResource true

pulumi preview --policy-pack ./policy
```

The policy should reject the simulated unexpected bucket because it lacks `Approved=true`.

For production, also:

- Use Pulumi Cloud or a tightly controlled state backend with SSO, MFA, RBAC, encryption, versioning, and audit logs.
- Prevent CI roles from editing or deleting backend state directly.
- Require protected branches and reviewed preview output.
- Pin provider and policy-pack versions.
- Never use `--disable-integrity-checking`.
- Alert on stack imports, state repairs, backend object rewrites, provider changes, and unexpected resource URNs.
- Keep production deployment credentials separate from state-administration credentials.
